# examples/doom/core/full/native_session.rb — the session, held by the playable program.
#
# Doom::Core::Session (session.rb) with Route (route.rb) is the session in
# CRuby. This is the same session for the program the pinned Spinel compiles:
# every buffer the schema declares is registry storage of the 0007 adapter,
# allocated once at its element and count and released once, and the program
# holds ids, never addresses.
#
# THE LAYOUT IS GENERATED, THE RULES ARE THESE. nativeprep.rb (generated by
# tools/doom/core-native-prep.rb) lists every schema field in order with its
# role, element, count and initial. The counts are resolved here against the
# catalog the program measured (native_catalog.rb), and the scalar rule is
# tools/doom/state-schema.rb's: a field of count 1, element i64 and role other
# than resource is a slot of the shared `core_state` buffer, in schema order;
# every other field is its own allocation.
#
# The registry operations are NativeFFI's (nativeprep.rb): the registry is
# shared by all three adapters, whose per-entry operations wrap it.
#
# A resource field may instead be BOUND, after the session opened, to memory
# the caller placed (bind_resource, decision 0021); tests/doom-core/bound-resources.sh
# binds every resource to a session image's read-only mapping.
module Doom
  module Core
    class NativeSessionError < StandardError; end

    class NativeSession
      ELEM_WIDTH = [0, 1, 4, 4, 8, 1, 2, 2]

      # result is an entry's i64 result, result32 an i32 one (decision 0022: an
      # entry at the target's width answers i32)
      attr_reader :result, :result32, :words, :input_slots, :step_slots, :render_slots, :render_zero

      def initialize(catalog)
        @catalog = catalog
        @ids = {}
        @counts = {}
        @slots = {}
        @elements = {}
        st = NativeFFI.spinel_adapter_registry_startup
        st == 0 or raise NativeSessionError, "the adapter registry would not start (#{st})"
        @words = alloc(3, 2)
        @result = alloc(4, 1)
        @result32 = alloc(2, 1)
        names = NativePrep::NAMES
        nslots = 0
        i = 0
        while i < names.length
          n = count_of(i)
          @counts[names[i]] = n
          @elements[names[i]] = NativePrep::ELEMENTS[i]
          if n == 1 && NativePrep::ELEMENTS[i] == 4 && NativePrep::ROLES[i] != "resource"
            @slots[names[i]] = nslots
            nslots += 1
          end
          i += 1
        end
        @nslots = nslots
        @state = alloc(4, nslots)
        @ids["core_state"] = @state
        i = 0
        while i < names.length
          nm = names[i]
          unless @slots.key?(nm)
            @ids[nm] = alloc(NativePrep::ELEMENTS[i], @counts[nm])
          end
          fill = NativePrep::FILLS[i]
          if NativePrep::PREPARED[i] == 0 && fill != 0
            k = 0
            while k < @counts[nm]
              put(nm, k, fill)
              k += 1
            end
          end
          i += 1
        end
        # fields.tsv's `derived:` index tables, one allocation each
        @input_slots = index_table(NativePrep::INPUT_SLOTS)
        @step_slots = index_table(NativePrep::STEP_SLOTS)
        @render_slots = index_table(NativePrep::RENDER_SLOTS)
        @render_zero = index_table(NativePrep::RENDER_ZERO)
      end

      def count_of(i)
        fixed = NativePrep::COUNT_FIXED[i]
        return fixed if fixed >= 0
        name = NativePrep::COUNT_NAMES[i]
        @catalog.key?(name) or
          raise NativeSessionError, "#{NativePrep::NAMES[i]} counts #{name}, which the catalog does not measure"
        @catalog[name]
      end

      def alloc(element, count)
        id = NativeFFI.spinel_adapter_registry_allocate(element, count)
        id > 0 or raise NativeSessionError, "the adapter would not allocate #{count} of element #{element}"
        id
      end

      def id(name)
        @ids.key?(name) or raise NativeSessionError, "#{name} is not a buffer of this session"
        @ids[name]
      end

      # DECISION 0021: A RESOURCE AT AN ADDRESS THE BOUNDARY DID NOT ALLOCATE.
      # Rebinds a resource field to `count` elements the caller placed at
      # `address` (a session image's resource part, mapped read-only), and
      # releases the storage the session allocated for it. Only a resource is
      # bound, and only at the count the schema and the catalog give it; the
      # adapter checks the address (non-NULL, aligned, no overflow) and from
      # then on refuses every write to it, so a put on the field raises.
      def bind_resource(name, address, count)
        i = 0
        while i < NativePrep::NAMES.length && NativePrep::NAMES[i] != name
          i += 1
        end
        i < NativePrep::NAMES.length or raise NativeSessionError, "#{name} is not a schema field"
        role = NativePrep::ROLES[i]
        role == "resource" or
          raise NativeSessionError, "#{name} is a #{role} field, not a resource; only a resource is bound"
        count == @counts[name] or
          raise NativeSessionError, "#{name} counts #{@counts[name]}, the image says #{count}"
        e = NativePrep::ELEMENTS[i]
        bound = NativeFFI.spinel_adapter_registry_bind(e, count, address)
        bound > 0 or
          raise NativeSessionError, "the adapter would not bind #{name} at #{address} (element #{e}, count #{count})"
        st = NativeFFI.spinel_adapter_registry_release(@ids[name])
        st == 0 or raise NativeSessionError, "releasing #{name}'s allocation answered #{st}"
        @ids[name] = bound
        bound
      end

      def slot(name)
        @slots.key?(name) or raise NativeSessionError, "#{name} is not a core_state slot"
        @slots[name]
      end

      def slot?(name)
        @slots.key?(name)
      end

      def count(name)
        @counts.key?(name) or raise NativeSessionError, "#{name} is not a schema field"
        @counts[name]
      end

      def put(name, i, v)
        if @slots.key?(name)
          i == 0 or raise NativeSessionError, "#{name} is a slot; index #{i}"
          put_i64(@state, @slots[name], v)
        elsif @elements[name] == 4
          put_i64(@ids[name], i, v)
        else
          st = NativeFFI.spinel_adapter_registry_store(@ids[name], i, v)
          st == 0 or raise NativeSessionError, "store #{name}[#{i}] = #{v} answered #{st}"
        end
      end

      def put_i64(id, i, v)
        st = NativeFFI.spinel_adapter_registry_store_i64_words(id, i, v & 0xffffffff, (v >> 32) & 0xffffffff)
        st == 0 or raise NativeSessionError, "store #{id}[#{i}] = #{v} answered #{st}"
      end

      def get_i64(id, i)
        st = NativeFFI.spinel_adapter_registry_load_i64_words(id, i, @words, 0, 1)
        st == 0 or raise NativeSessionError, "load #{id}[#{i}] answered #{st}"
        lo = NativeFFI.spinel_adapter_registry_load(@words, 0)
        hi = NativeFFI.spinel_adapter_registry_load(@words, 1)
        # Signed without a literal outside i64: a literal of 2**63 or 2**64 is
        # not an i64 on this pin, and a value computed with one is not either.
        hi >= 2_147_483_648 ? ((hi - 4_294_967_296) << 32) | lo : (hi << 32) | lo
      end

      def get(name, i)
        return get_i64(@state, @slots[name]) if @slots.key?(name)
        return get_i64(@ids[name], i) if @elements[name] == 4
        # One call: the element's unsigned 32-bit pattern, or a negative status.
        v = NativeFFI.spinel_adapter_registry_load(@ids[name], i)
        v >= 0 or raise NativeSessionError, "load #{name}[#{i}] answered #{v}"
        e = @elements[name]
        (e == 2 || e == 5 || e == 7) && v >= 2_147_483_648 ? v - 4_294_967_296 : v
      end

      # An index table (fields.tsv's `derived:TABLE`): position k holds the
      # core_state slot of the k-th name.
      def index_table(names)
        id = alloc(4, names.length)
        k = 0
        while k < names.length
          put_i64(id, k, slot(names[k]))
          k += 1
        end
        id
      end

      # The canonical snapshot (state-schema.rb's snapshot.tsv): schema order,
      # little endian, scratch left out.
      def write_snapshot(path)
        total = 0
        names = NativePrep::NAMES
        i = 0
        while i < names.length
          total += @counts[names[i]] * ELEM_WIDTH[NativePrep::ELEMENTS[i]] if NativePrep::ROLES[i] != "scratch"
          i += 1
        end
        buf = Doom::Bytes.buffer(total, 0)
        at = 0
        i = 0
        while i < names.length
          if NativePrep::ROLES[i] != "scratch"
            nm = names[i]
            w = ELEM_WIDTH[NativePrep::ELEMENTS[i]]
            k = 0
            while k < @counts[nm]
              v = get(nm, k)
              b = 0
              while b < w
                buf.setbyte(at, (v >> (8 * b)) & 255)
                at += 1
                b += 1
              end
              k += 1
            end
          end
          i += 1
        end
        File.open(path, "wb") { |f| f.write(buf) }
        total
      end
    end
  end
end
